from lib import *
S = SS('p38')
steps = [
    step("请求队列共 180 个:40 个商品页各以 Accept-Language 为 en 和 zh 请求(80 个);POST /search 20 种请求体各重复 3 次(60 个);/account/ 10 个 URL 各以 Cookie 为 tier=free 和 tier=pro 请求(20 个);/about 重复 10 次;GET /search?q= 10 个。把 180 个请求全部发一遍的标准答案:服务器返回 131 种不同的内容(商品页 80 + POST 搜索 20 + GET 搜索 10 + 账号页 20 + /about 1)。", t=tl(S(1)), done=lidx(S(1), '131 种不同的内容'), b=bars([['请求总数', 180, '180'], ['不同的内容', 131, '131']], 180, done=[1]), kv=KV([['请求总数', '180'], ['真实不同的内容', '131'], ['真正的重复', '49 个']], ['真实不同的内容'])),
    step("按指纹去重(同一个指纹只发第一个请求)之后:只哈希 URL —— 发出 62 个请求,拿到 62 种不同内容,漏掉 69 种;方法 + URL —— 同样 62 个、漏 69(这个队列里没有 URL 相同、方法不同的请求);方法 + URL + 请求体 —— 81 个、漏 50;方法 + URL + 请求体 + 关键请求头(Accept-Language、Cookie)—— 131 个请求,拿到 131 种,漏 0,也没有多发重复。每个方案多发的重复都是 0,但漏掉的是实打实的不同页面。", t=tl(S(2)), done=lidx(S(2), '关键请求头'), mark=lidx(S(2), '只哈希 URL', '方法 + URL  ', '方法 + URL + 请求体  '), b=bars([['只哈希 URL:漏掉', 69, '69'], ['方法 + URL:漏掉', 69, '69'], ['+ 请求体:漏掉', 50, '50'], ['+ 请求头:漏掉', 0, '0']], 70, mark=[0, 1, 2], done=[3]), kv=KV([['只哈希 URL', '漏掉 69 种内容'], ['再加请求体', '漏 50'], ['再加 Accept-Language 与 Cookie', '漏 0']], ['再加 Accept-Language 与 Cookie'])),
    step("只哈希 URL 时被当成重复丢掉、实际内容不同的请求:商品页带 Accept-Language(zh 版本被 en 版本挡掉)40 个;/account 带不同 Cookie(pro 页被 free 页挡掉)10 个;POST /search 的不同请求体 19 个(同一个 URL 只发了第一个请求体)。共 40 + 10 + 19 = 69 个。", t=tl(S(3)), done=lidx(S(3), 'product', 'account', 'search POST'), b=bars([['商品页(Accept-Language)', 40, '40'], ['账号页(Cookie)', 10, '10'], ['POST 搜索(请求体)', 19, '19']], 40, mark=[0, 1, 2]), kv=KV([['Accept-Language', '40 个页面被漏'], ['Cookie', '10 个'], ['POST 请求体', '19 个']], ['Accept-Language'])),
    step("请求体也要规范化后再哈希:q=word1&page=2 与 page=2&q=word1,本服务器对两者返回相同的内容;按原始字节哈希,两者的指纹不同(会多抓一次);解析成键值对、排序、再哈希,两者指纹相同。但“参数顺序无关”是服务器的行为,对别的服务器未必成立。", t=tl(S(4)), done=lidx(S(4), '请求体 \'q=word1&page=2\''), kv=KV([['按原始字节哈希', '两种顺序指纹不同'], ['解析、排序后哈希', '指纹相同'], ['前提', '服务器本身与参数顺序无关']], ['前提'])),
]
A = mkartp('p38', 38, '爬虫,请求指纹,去重,POST,Accept-Language,Cookie,Python,真实验证,动画演示',
    '构造一个响应取决于方法、请求体、Accept-Language 和 Cookie 的本机服务器:180 个请求有 131 种不同的内容;只哈希 URL 去重只拿到 62 种、漏掉 69 种(40 个 Accept-Language 版本、10 个 Cookie 版本、19 个 POST 请求体);把方法、请求体、关键请求头都放进指纹才拿到全部 131 种。',
    '只用 URL 判断两个请求是不是同一个,在 GET 页面上通常够用。可一旦服务器按请求体、语言头或 Cookie 返回不同的内容,URL 相同的请求其实是不同的页面。这篇构造这样的服务器,看四种指纹方案各自漏掉多少。',
    [('62 对 131', '只哈希 URL 与带上方法、请求体、关键请求头的指纹,各自拿到的不同内容数'), ('69', '只哈希 URL 时被当成重复丢掉的不同页面数'), ('0 个多发', '这四种方案多发的重复请求都是 0——代价只在漏抓')],
    [('标准答案', '<p>180 个请求发一遍,服务器返回 131 种不同的内容。其中 49 个是真正的重复(/about 重复 10 次、POST 搜索每个重复 2 次等)。</p>'),
     ('四种指纹', '<p>只哈希 URL 或哈希“方法 + URL”只抓到 62 种,漏掉 69 种;加上请求体 81 种;再加上 <code>Accept-Language</code> 和 <code>Cookie</code> 才是 131 种,不漏也不多发。爬虫的指纹应当包含所有会影响响应的请求要素。</p>'),
     ('漏的是哪些', '<p>URL 相同、<code>Accept-Language</code> 不同的 40 个商品页;URL 相同、<code>Cookie</code> 不同的 10 个账号页;URL 相同、请求体不同的 19 个 POST 搜索。这些在“只哈希 URL”的指纹下统统被当作重复,没有任何报错。</p>'),
     ('请求体规范化', '<p>请求体的参数顺序不同,按原始字节哈希会得到不同的指纹(多抓一次);解析后排序再哈希则相同。这只在服务器对参数顺序不敏感时才合理。把哪些请求头纳入指纹,是个取舍:纳入太多会让指纹碎片化(每个请求头都不同),太少则漏抓。</p>')],
    steps,
    [ENV_P + '。服务器按路径决定内容:商品页取决于 Accept-Language,/account 取决于 Cookie 里的 tier,/search 取决于请求方式和 q;请求队列是手工构造的 180 个请求;“标准答案”是把 180 个都发一遍后的不同内容数;指纹方案是纯 Python 函数,按指纹去重只发每个指纹的第一个请求',
     '没有验证:真实站点里请求头对内容的影响(User-Agent、Referer 等是否也该进指纹);Scrapy 的 request_fingerprint 具体包含哪些要素(没有安装);带 Cookie 的会话状态变化(登录之后同一个 URL 内容变了);指纹碎片化的量化;不同内容但语义等价的页面(近似去重,后面有 SimHash 一篇)'],
    '请求指纹')
